mapper.select:
SELECT * FROM sms_flash_promotion_record
WHERE order_id = #{orderId}
LIMIT 1

mapper.update:
UPDATE sms_flash_promotion_record
SET status = #{toStatus}
WHERE id = #{id} AND status = #{fromStatus}

UPDATE sms_flash_promotion_record
SET order_id = #{orderId}, order_sn = #{orderSn}, status = #{status}
WHERE id = #{id} AND status IN (0, 10)

UPDATE sms_flash_promotion_record
SET status = #{status},
    error_msg = #{errorMsg},
    retry_count = retry_count + 1
WHERE id = #{id}

    AND status = #{fromStatus}

mapper.select:
SELECT id FROM sms_flash_promotion_record
WHERE status = #{status} AND create_time < #{before}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE sms_flash_promotion_record
SET status = #{status}
WHERE order_id = #{orderId} AND (status IS NULL OR status <> #{status})
